script:
await step('Mở Dashboard Tổng quan SCM (/scm/dashboard)', async () => {
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  assert(/\/scm\/dashboard/.test(page.url()), 'Không vào được Dashboard SCM');
  const txt = await page.locator('body').innerText();
  assert(txt.length > 50, 'Nội dung Dashboard SCM trống');
});

await step('Kiểm tra Báo cáo Số liệu vận hành SCM (/scm/report/operating)', async () => {
  await page.goto('https://tasks.zuizui.io/scm/report/operating', { waitUntil: 'domcontentloaded' });
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  assert(/\/scm\/report\/operating/.test(page.url()), 'Không mở được Báo cáo Số liệu vận hành SCM');
});

await step('Kiểm tra Báo cáo Theo khu vực, đơn vị SCM (/scm/report/store)', async () => {
  await page.goto('https://tasks.zuizui.io/scm/report/store', { waitUntil: 'domcontentloaded' });
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  assert(/\/scm\/report\/store/.test(page.url()), 'Không mở được Báo cáo theo đơn vị SCM');
  ctx.log('Đã kiểm tra đầy đủ Dashboard và Báo cáo SCM.');
});
